      $('#l12PortN', root).innerHTML = legendRow(series.map(s => ({ name: s.name, color: s.color, sq: true }))) + `The same monthly budget, re-split each month by season. Repair and heating trade places between July and January; replacement holds the middle; maintenance and indoor air take the shoulders. ${MM(tot.b * 12)} a year at ${M$(st.budget)} a month.`;
